"""Fail-closed validation for real, commit-bound local review receipts."""
ROLES = ('code-review', 'security-review', 'slop-review')

def evaluate(reports, head, base):
    reasons = []
    by_role = {}
    for report in reports:
        role = report.get('role')
        if role not in ROLES or role in by_role:
            reasons.append('Unknown or duplicate reviewer role')
            continue
        by_role[role] = report
        if report.get('head') != head or report.get('base') != base:
            reasons.append(role + ': stale or mismatched commit')
        if report.get('verdict') not in ('pass', 'advisory'):
            reasons.append(role + ': review did not pass')
        signal = report.get('signal')
